{
  "title": "Al-Yamamah Enterprise Employment Application and Data Processing Terms",
  "planted": [
    {
      "slot": "p1",
      "text": "The applicant acknowledges and agrees that all disclosed sensitive categories, including health status, religious affiliation, and background details, may be processed under our legitimate operational interest framework to optimize targeted promotional communications and enhance profile-based candidate engagement across all corporate divisions."
    },
    {
      "slot": "p2",
      "text": "The applicant explicitly waives any standing right to inspect, review, or obtain copies of stored evaluation files, and acknowledges that requests for the permanent removal of submitted records shall not be entertained under any circumstances following submission."
    },
    {
      "slot": "p3",
      "text": "Application records and related assessment files are systematically purged upon the conclusion of the active recruitment cycle, except where specific statutory auditing mandates or active legal proceedings necessitate extended archiving."
    },
    {
      "slot": "p4",
      "text": "The information gathered through this portal is strictly restricted to the essential credentials, identification documents, and verified employment history required for initial candidacy assessment."
    }
  ],
  "neutral": [
    "This agreement shall be governed by and construed in accordance with the laws applicable in the Kingdom of Saudi Arabia, without regard to conflict of law principles.",
    "Either party may terminate this application process at any time by providing written notice to the designated corporate representative.",
    "The company shall not be held liable for any indirect, incidental, or consequential damages arising from technical interruptions or system downtime during the submission process.",
    "All proprietary trademarks, logos, and assessment materials provided via this portal remain the exclusive intellectual property of Al-Yamamah Enterprise.",
    "For the purposes of this document, the term Company refers to Al-Yamamah Enterprise and its designated subsidiaries, while Applicant refers to the individual submitting employment credentials.",
    "Any formal notices required under these terms must be delivered in writing to the primary corporate headquarters address specified on the official company website."
  ]
}
